"""Background escalation worker for the durable store."""

from __future__ import annotations

from collections.abc import Callable

from .models import Incident
from .sqlite_store import SQLiteIncidentStore


class EscalationWorker:
    """Pulls overdue incidents, escalates them, and clears stale claims.

    A single ``run_once`` either claims the oldest overdue incident (if no claim
    is held by this worker yet) or completes any outstanding escalation owned
    by this worker. ``run_until_idle`` repeats until no work remains.
    """

    def __init__(
        self,
        store: SQLiteIncidentStore,
        worker_id: str,
        clock: Callable[[], float] | None = None,
    ) -> None:
        self.store = store
        self.worker_id = worker_id
        self._clock = clock

    def run_once(self, now: float | None = None) -> Incident | None:
        if now is not None:
            timestamp = now
        elif self._clock is not None:
            timestamp = self._clock()
        else:
            timestamp = None

        self.store.recover_expired_claims(now=timestamp)
        claimed = self.store.claim_due_escalation(self.worker_id, now=timestamp)
        if claimed is None:
            return None
        return self.store.complete_escalation(claimed.id, self.worker_id, now=timestamp)

    def run_until_idle(
        self,
        max_incidents: int | None = None,
        now: float | None = None,
    ) -> list[Incident]:
        results: list[Incident] = []
        while True:
            if max_incidents is not None and len(results) >= max_incidents:
                break
            incident = self.run_once(now=now)
            if incident is None:
                break
            results.append(incident)
        return results

"""Standard-library HTTP server for the durable incident-operations app."""

from __future__ import annotations

import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from .models import (
    Incident,
    IncidentError,
    IncidentNotFound,
    IncidentStatus,
    InvalidTransition,
    Severity,
    VersionConflict,
)
from .sqlite_store import SQLiteIncidentStore
from .escalation import EscalationWorker

STATIC_DIR = Path(__file__).with_name("static")

_INCIDENT_DETAIL_RE = re.compile(r"^/api/incidents/([^/]+)$")


def _severity_values() -> list[str]:
    return [s.value for s in Severity]


def _status_values() -> list[str]:
    return [s.value for s in IncidentStatus]


def _incident_to_dict(incident: Incident) -> dict:
    return {
        "id": incident.id,
        "fingerprint": incident.fingerprint,
        "title": incident.title,
        "severity": incident.severity.value,
        "status": incident.status.value,
        "owner": incident.owner,
        "alert_count": incident.alert_count,
        "version": incident.version,
        "escalation_level": incident.escalation_level,
        "created_at": incident.created_at,
        "updated_at": incident.updated_at,
        "sla_deadline": incident.sla_deadline,
        "escalation_claimed_by": incident.escalation_claimed_by,
        "escalation_claimed_at": incident.escalation_claimed_at,
    }


def _event_to_dict(event) -> dict:
    return {
        "id": event.id,
        "incident_id": event.incident_id,
        "type": event.type,
        "timestamp": event.timestamp,
        "details": event.details,
    }


def create_server(
    store: SQLiteIncidentStore,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop."""

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            path = self.path.split("?", 1)[0]
            if path == "/api/incidents":
                params = self._query_params()
                try:
                    incidents = store.list(
                        status=params.get("status"),
                        severity=params.get("severity"),
                        owner=params.get("owner"),
                    )
                except ValueError as exc:
                    self._json(400, {"error": str(exc)})
                    return
                self._json(200, [_incident_to_dict(i) for i in incidents])
                return
            if path == "/api/summary":
                self._json(200, store.summary())
                return
            match = _INCIDENT_DETAIL_RE.match(path)
            if match:
                incident_id = match.group(1)
                incident = store.get(incident_id)
                if incident is None:
                    self._json(404, {"error": f"incident {incident_id} not found"})
                    return
                events = store.events(incident_id)
                payload = _incident_to_dict(incident)
                payload["events"] = [_event_to_dict(e) for e in events]
                self._json(200, payload)
                return
            if path in {"/", "/index.html"}:
                self._file("index.html", "text/html; charset=utf-8")
                return
            if path == "/app.js":
                self._file("app.js", "text/javascript; charset=utf-8")
                return
            if path == "/styles.css":
                self._file("styles.css", "text/css; charset=utf-8")
                return
            self.send_error(404)

        def do_POST(self) -> None:
            path = self.path.split("?", 1)[0]
            if path == "/api/alerts":
                try:
                    payload = self._body()
                except json.JSONDecodeError as exc:
                    self._json(400, {"error": f"invalid JSON: {exc}"})
                    return
                fingerprint = payload.get("fingerprint")
                title = payload.get("title")
                severity = payload.get("severity")
                if not fingerprint or not str(fingerprint).strip():
                    self._json(400, {"error": "fingerprint is required"})
                    return
                if not title or not str(title).strip():
                    self._json(400, {"error": "title is required"})
                    return
                try:
                    incident, created = store.ingest_alert(
                        fingerprint=str(fingerprint),
                        title=str(title),
                        severity=severity,
                        source=payload.get("source", "unknown"),
                        details=payload.get("details"),
                        idempotency_key=payload.get("idempotency_key"),
                    )
                except ValueError as exc:
                    self._json(400, {"error": str(exc)})
                    return
                self._json(201 if created else 200, _incident_to_dict(incident))
                return
            if path == "/api/escalations/run":
                payload = {}
                try:
                    body_text = self._raw_body()
                    if body_text:
                        payload = json.loads(body_text)
                except json.JSONDecodeError:
                    payload = {}
                worker_id = payload.get("worker_id", "worker-1")
                max_incidents = payload.get("max_incidents")
                try:
                    worker = EscalationWorker(store, worker_id)
                    incidents = worker.run_until_idle(
                        max_incidents=max_incidents if isinstance(max_incidents, int) else None
                    )
                except IncidentError as exc:
                    self._json(409, {"error": str(exc)})
                    return
                self._json(
                    200,
                    {"escalated": [_incident_to_dict(i) for i in incidents]},
                )
                return
            self.send_error(404)

        def do_PATCH(self) -> None:
            path = self.path.split("?", 1)[0]
            match = _INCIDENT_DETAIL_RE.match(path)
            if not match:
                self.send_error(404)
                return
            incident_id = match.group(1)
            try:
                payload = self._body()
            except json.JSONDecodeError as exc:
                self._json(400, {"error": f"invalid JSON: {exc}"})
                return
            expected_version = payload.get("expected_version")
            if not isinstance(expected_version, int):
                self._json(400, {"error": "expected_version is required"})
                return
            try:
                incident = store.update(
                    incident_id=incident_id,
                    expected_version=expected_version,
                    owner=payload.get("owner"),
                    status=payload.get("status"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except IncidentNotFound:
                self._json(404, {"error": f"incident {incident_id} not found"})
                return
            except VersionConflict as exc:
                self._json(409, {"error": str(exc), "current_version": True})
                return
            except InvalidTransition as exc:
                self._json(422, {"error": str(exc)})
                return
            except ValueError as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, _incident_to_dict(incident))

        def _query_params(self) -> dict[str, str]:
            parts = self.path.split("?", 1)
            if len(parts) == 1:
                return {}
            result: dict[str, str] = {}
            for chunk in parts[1].split("&"):
                if not chunk:
                    continue
                if "=" in chunk:
                    key, value = chunk.split("=", 1)
                    result[key] = value
                else:
                    result[chunk] = ""
            return result

        def _raw_body(self) -> bytes:
            length = int(self.headers.get("Content-Length", "0") or 0)
            if length <= 0:
                return b""
            return self.rfile.read(length)

        def _body(self) -> dict:
            raw = self._raw_body()
            if not raw:
                return {}
            return json.loads(raw)

        def _file(self, name: str, content_type: str) -> None:
            body = (STATIC_DIR / name).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=str).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    return ThreadingHTTPServer((host, port), Handler)

const app = document.querySelector("#app");
const summaryTiles = document.querySelector(".summary-tiles");
const alertForm = document.querySelector("#alert-form");
const statusFilter = document.querySelector("#status-filter");
const severityFilter = document.querySelector("#severity-filter");
const escalateBtn = document.querySelector("#escalate-btn");
const refreshBtn = document.querySelector("#refresh-btn");
const feedback = document.querySelector("#feedback");
const incidentList = document.querySelector("#incident-list");
const incidentDetail = document.querySelector("#incident-detail");
const timelineList = document.querySelector("#timeline-list");

const state = {
  status: "",
  severity: "",
  selectedId: null,
  incidents: [],
  detail: null,
  feedback: "",
};

function setFeedback(message, ok = true) {
  state.feedback = message || "";
  feedback.textContent = message || "";
  feedback.classList.toggle("error", Boolean(message) && !ok);
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.status) params.set("status", state.status);
  if (state.severity) params.set("severity", state.severity);
  const query = params.toString() ? `?${params.toString()}` : "";
  try {
    const response = await fetch(`/api/incidents${query}`);
    state.incidents = await response.json();
  } catch (error) {
    setFeedback(`Failed to load incidents: ${error.message}`, false);
    state.incidents = [];
  }
  renderSummary();
  renderList();
  if (state.selectedId) {
    await selectIncident(state.selectedId);
  }
}

async function selectIncident(id) {
  state.selectedId = id;
  try {
    const response = await fetch(`/api/incidents/${encodeURIComponent(id)}`);
    if (!response.ok) {
      const err = await response.json().catch(() => ({}));
      setFeedback(`Could not load incident: ${err.error || response.status}`, false);
      state.detail = null;
      renderDetail();
      renderList();
      return;
    }
    state.detail = await response.json();
    renderDetail();
    renderTimeline();
    renderList();
  } catch (error) {
    setFeedback(`Failed to load detail: ${error.message}`, false);
    state.detail = null;
    renderDetail();
  }
}

function renderSummary() {
  const tiles = [];
  const total = state.incidents.length;
  const byStatus = {open: 0, acknowledged: 0, resolved: 0};
  const bySeverity = {P1: 0, P2: 0, P3: 0, P4: 0};
  for (const item of state.incidents) {
    byStatus[item.status] = (byStatus[item.status] || 0) + 1;
    bySeverity[item.severity] = (bySeverity[item.severity] || 0) + 1;
  }
  tiles.push(`<div class="tile"><span class="tile-label">Total</span><span class="tile-value">${total}</span></div>`);
  for (const status of ["open", "acknowledged", "resolved"]) {
    tiles.push(`<div class="tile tile-${status}"><span class="tile-label">${status}</span><span class="tile-value">${byStatus[status] || 0}</span></div>`);
  }
  for (const sev of ["P1", "P2", "P3", "P4"]) {
    tiles.push(`<div class="tile tile-${sev}"><span class="tile-label">${sev}</span><span class="tile-value">${bySeverity[sev] || 0}</span></div>`);
  }
  summaryTiles.innerHTML = tiles.join("");
}

function incidentRow(item) {
  const li = document.createElement("li");
  li.setAttribute("data-testid", "incident-row");
  li.dataset.id = item.id;
  li.className = `incident-row status-${item.status} severity-${item.severity}`;
  if (state.selectedId === item.id) li.classList.add("selected");
  li.innerHTML = `
    <div class="row-head">
      <span class="badge badge-${item.severity}">${item.severity}</span>
      <span class="row-title"></span>
      <span class="badge badge-${item.status}">${item.status}</span>
    </div>
    <div class="row-meta">
      <span>v${item.version}</span>
      <span>alerts ${item.alert_count}</span>
      <span>escalations ${item.escalation_level}</span>
      ${item.owner ? `<span>owner ${escapeHtml(item.owner)}</span>` : ""}
    </div>
  `;
  li.querySelector(".row-title").textContent = item.title;
  li.addEventListener("click", () => selectIncident(item.id));
  return li;
}

function renderList() {
  const items = state.incidents.map(incidentRow);
  incidentList.replaceChildren(...items);
}

function renderDetail() {
  if (!state.detail) {
    incidentDetail.innerHTML = `<p class="placeholder">Select an incident to see details.</p>`;
    return;
  }
  const i = state.detail;
  const claimed = i.escalation_claimed_by ? `claimed by ${escapeHtml(i.escalation_claimed_by)}` : "not claimed";
  incidentDetail.innerHTML = `
    <h3 class="detail-title"></h3>
    <dl class="detail-grid">
      <dt>ID</dt><dd><code>${escapeHtml(i.id)}</code></dd>
      <dt>Status</dt><dd>${i.status}</dd>
      <dt>Severity</dt><dd>${i.severity}</dd>
      <dt>Owner</dt><dd>${i.owner ? escapeHtml(i.owner) : "unassigned"}</dd>
      <dt>Version</dt><dd>${i.version}</dd>
      <dt>Alerts</dt><dd>${i.alert_count}</dd>
      <dt>Escalations</dt><dd>${i.escalation_level}</dd>
      <dt>Fingerprint</dt><dd><code>${escapeHtml(i.fingerprint)}</code></dd>
      <dt>SLA deadline</dt><dd>${formatTime(i.sla_deadline)}</dd>
      <dt>Updated</dt><dd>${formatTime(i.updated_at)}</dd>
      <dt>Claim</dt><dd>${claimed}</dd>
    </dl>
    <div class="detail-actions">
      <label class="field">Owner
        <input data-testid="owner-input" id="owner-input" value="${escapeAttr(i.owner || "")}" placeholder="assignee">
      </label>
      <button data-testid="acknowledge-action" id="ack-btn" type="button" ${i.status === "open" ? "" : "disabled"}>Acknowledge</button>
      <button data-testid="resolve-action" id="resolve-btn" type="button" ${i.status === "resolved" ? "disabled" : ""}>Resolve</button>
      <button id="save-owner-btn" type="button">Save owner</button>
    </div>
  `;
  incidentDetail.querySelector(".detail-title").textContent = i.title;
  incidentDetail.querySelector("#ack-btn").addEventListener("click", () => patchIncident({status: "acknowledged"}));
  incidentDetail.querySelector("#resolve-btn").addEventListener("click", () => patchIncident({status: "resolved"}));
  incidentDetail.querySelector("#save-owner-btn").addEventListener("click", () => {
    const value = incidentDetail.querySelector("#owner-input").value;
    patchIncident({owner: value});
  });
}

function renderTimeline() {
  if (!state.detail || !state.detail.events) {
    timelineList.replaceChildren();
    return;
  }
  const items = state.detail.events.map((event) => {
    const li = document.createElement("li");
    li.className = `event event-${event.type}`;
    li.innerHTML = `
      <span class="event-time">${formatTime(event.timestamp)}</span>
      <span class="event-type">${event.type}</span>
      <span class="event-details"></span>
    `;
    li.querySelector(".event-details").textContent = JSON.stringify(event.details);
    return li;
  });
  timelineList.replaceChildren(...items);
}

async function patchIncident(changes) {
  if (!state.detail) return;
  const payload = {expected_version: state.detail.version, ...changes};
  try {
    const response = await fetch(`/api/incidents/${encodeURIComponent(state.detail.id)}`, {
      method: "PATCH",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify(payload),
    });
    const data = await response.json();
    if (response.ok) {
      setFeedback("Incident updated");
      await selectIncident(state.detail.id);
      await refresh();
    } else if (response.status === 409) {
      setFeedback(`Conflict: ${data.error || "stale version"}`, false);
      await selectIncident(state.detail.id);
    } else {
      setFeedback(`${data.error || "update failed"}`, false);
    }
  } catch (error) {
    setFeedback(`Update failed: ${error.message}`, false);
  }
}

async function ingestAlert(payload) {
  const response = await fetch("/api/alerts", {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify(payload),
  });
  const data = await response.json().catch(() => ({}));
  if (response.status === 201) {
    setFeedback(`Created incident ${data.id}`);
    state.selectedId = data.id;
    await refresh();
  } else if (response.status === 200) {
    setFeedback(`Merged duplicate alert into ${data.id}`);
    state.selectedId = data.id;
    await refresh();
  } else {
    setFeedback(data.error || "Could not ingest alert", false);
  }
}

async function runEscalations() {
  try {
    const response = await fetch("/api/escalations/run", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({worker_id: "browser", max_incidents: 25}),
    });
    const data = await response.json().catch(() => ({}));
    if (response.ok) {
      setFeedback(`Escalated ${data.escalated ? data.escalated.length : 0} incident(s)`);
      await refresh();
    } else {
      setFeedback(data.error || "Escalation failed", false);
    }
  } catch (error) {
    setFeedback(`Escalation failed: ${error.message}`, false);
  }
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

function escapeAttr(value) {
  return escapeHtml(value);
}

function formatTime(ts) {
  if (!ts) return "-";
  return new Date(ts * 1000).toISOString().replace("T", " ").replace(/\.\d+Z$/, "Z");
}

function getState() {
  return {
    status: state.status,
    severity: state.severity,
    selectedId: state.selectedId,
    incidents: state.incidents,
    feedback: state.feedback,
  };
}

alertForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const data = Object.fromEntries(new FormData(alertForm));
  ingestAlert(data);
  alertForm.reset();
});

statusFilter.addEventListener("change", () => {
  state.status = statusFilter.value;
  refresh();
});

severityFilter.addEventListener("change", () => {
  state.severity = severityFilter.value;
  refresh();
});

escalateBtn.addEventListener("click", runEscalations);
refreshBtn.addEventListener("click", refresh);

window.incidentOps = {refresh, selectIncident, getState};

refresh();

:root {
  --bg: #eef2f7;
  --panel: #ffffff;
  --border: #d8e0ea;
  --text: #172033;
  --muted: #61708c;
  --accent: #3154a5;
  --danger: #b3261e;
  --warn: #9a6700;
  --ok: #1b5e20;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
}

* { box-sizing: border-box; }

body { margin: 0; }

main {
  width: 100%;
  max-width: 960px;
  margin: 0 auto;
  padding: 16px;
  display: grid;
  gap: 16px;
}

header, .alerts, .filters, .summary, .column, #incident-detail, #timeline {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
}

.eyebrow { color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .08em; margin: 0; }
h1 { margin: 6px 0 4px; font-size: 1.5rem; }
h2 { margin: 0 0 12px; font-size: 1.1rem; }
h3 { margin: 0 0 8px; font-size: 1rem; }
p { margin: 0; }

form { display: grid; gap: 10px; }
label { display: grid; gap: 4px; font-size: .85rem; color: var(--muted); }
input, select, button {
  box-sizing: border-box;
  min-height: 40px;
  padding: 8px 10px;
  font: inherit;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
}
button {
  border: 0;
  color: #fff;
  background: var(--accent);
  font-weight: 700;
  cursor: pointer;
}
button:disabled { background: #9aa6bb; cursor: not-allowed; }
button#escalate-btn { background: #6b3f8e; }
button#save-owner-btn { background: #3b6b8e; }

#alert-form {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}
#alert-form button { grid-column: 1 / -1; }

.summary-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 8px;
}
.tile {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px;
  border-radius: 10px;
  background: #f4f7fb;
  border: 1px solid var(--border);
  min-width: 0;
}
.tile-label { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.tile-value { font-size: 1.4rem; font-weight: 700; }
.tile-open { background: #fff4e5; }
.tile-acknowledged { background: #e5f0ff; }
.tile-resolved { background: #e8f5e9; }
.tile-P1 { background: #fdecea; color: #612018; }
.tile-P2 { background: #fff3e0; }
.tile-P3 { background: #fff8e1; }
.tile-P4 { background: #eef9ff; }

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: end;
}
.filters label { flex: 1 1 120px; }
.filters button { flex: 0 0 auto; }

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
  gap: 16px;
  align-items: start;
}

#incident-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.incident-row {
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
  cursor: pointer;
  min-width: 0;
}
.incident-row.selected { outline: 2px solid var(--accent); }
.incident-row.status-resolved { opacity: .7; }
.row-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.row-title { flex: 1; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
  font-size: .75rem;
  color: var(--muted);
}
.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: .72rem;
  font-weight: 700;
  background: #eef2f7;
}
.badge-P1 { background: #fde0dd; color: #612018; }
.badge-P2 { background: #ffe8cc; }
.badge-P3 { background: #fff3cd; }
.badge-P4 { background: #e1f0ff; }
.badge-open { background: #fff4e5; }
.badge-acknowledged { background: #e5f0ff; }
.badge-resolved { background: #e8f5e9; }

.detail-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin: 8px 0 12px;
  font-size: .85rem;
  word-break: break-word;
}
.detail-grid dt { color: var(--muted); }
.detail-grid dd { margin: 0; }
.detail-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: end; }
.detail-actions label { flex: 1 1 140px; }
.detail-actions button { flex: 0 0 auto; }
#ack-btn { background: #c97a00; }
#resolve-btn { background: var(--ok); }
.placeholder { color: var(--muted); }

#timeline ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
  max-height: 320px;
  overflow-y: auto;
}
.event {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  background: #f7f9fc;
  border: 1px solid var(--border);
  font-size: .78rem;
  align-items: start;
  word-break: break-word;
}
.event-time { color: var(--muted); white-space: nowrap; }
.event-type { font-weight: 700; }
.event-details { color: #41506c; overflow-wrap: anywhere; }

#feedback.error { color: var(--danger); }
#feedback { min-height: 1.2rem; }

@media (max-width: 720px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
  #alert-form { grid-template-columns: 1fr; }
  .detail-grid { grid-template-columns: 1fr; }
  .detail-grid dt { margin-top: 6px; }
}

@media (max-width: 390px) {
  main { padding: 8px; gap: 8px; }
  header, .alerts, .filters, .summary, .column, #incident-detail, #timeline { padding: 10px; border-radius: 10px; }
  h1 { font-size: 1.2rem; }
  .tile { padding: 6px; }
  .tile-value { font-size: 1.05rem; }
  .filters { gap: 6px; }
  .event { grid-template-columns: 1fr; }
}

